int hex_to_bytes(const char* hex, uint8_t* out, size_t out_len) {
    for (size_t i = 0; i < out_len; i++) {
        if (sscanf_s(&hex[2 * i], "%2hhx", &out[i]) != 1) {
            return -1;
        }
    }
    return 0;
}
// Print bytes
void print_hex(const uint8_t* data, size_t len) {
    for (size_t i = 0; i < len; ++i) {
        printf("%02X", data[i]);
        if ((i + 1) % 32 == 0) printf("\n");
    }
    printf("\n");
}

int main() {
    const char* message_hex =
        "";

    // Check length
    if (strlen(message_hex) < CT_HEX_LEN) {
        fprintf(stderr, "Provided hex string is too short (%zu < %d).\n", strlen(message_hex), CT_HEX_LEN);
        return 1;
    }

    // Extract ciphertext from message hex
    char ct_hex[CT_HEX_LEN + 1];
    strncpy(ct_hex, message_hex, CT_HEX_LEN);
    ct_hex[CT_HEX_LEN] = '\0';

    uint8_t ct[pqcrystals_kyber512_ref_CIPHERTEXTBYTES];
    hex_to_bytes(ct_hex, ct, pqcrystals_kyber512_ref_CIPHERTEXTBYTES);

    // Load receiver secret key
    uint8_t sk[pqcrystals_kyber512_ref_SECRETKEYBYTES];
    FILE* fp = fopen(SK_FILE, "rb");
    if (!fp || fread(sk, 1, sizeof(sk), fp) != sizeof(sk)) {
        fprintf(stderr, "Failed to load secret key from '%s'\n", SK_FILE);
        return 1;
    }
    fclose(fp);

    // Decapsulate
    uint8_t ss[pqcrystals_kyber512_ref_BYTES];
    if (pqcrystals_kyber512_ref_dec(ss, ct, sk) != 0) {
        fprintf(stderr, "Kyber decapsulation failed.\n");
        return 1;
    }

    // Print shared secret
    printf("Decapsulated shared secret:\n");
    print_hex(ss, pqcrystals_kyber512_ref_BYTES);

    return 0;
}
#endif
